@MainActor
final class CoverSource {
    private var pending: [Int: (UIImage) -> Void] = [:]
    func load(id: Int, done: @escaping (UIImage) -> Void) {
        pending[id] = done
    }
    func finish(id: Int, image: UIImage) {
        pending.removeValue(forKey: id)?(image)
    }
}
@MainActor
func requestCover(cell: GameCell, id: Int, source: CoverSource) {
    source.load(id: id) { [weak cell] image in
        cell?.imageView?.image = image
        cell?.setNeedsLayout()
    }
}
@MainActor
func checkLateCover() {
    let source = CoverSource()
    let cell = GameCell(style: .default, reuseIdentifier: "Game")
    let first = Game(id: 61, title: "Маяки", saved: true)
    let second = Game(id: 62, title: "Остров", saved: false)
    let oldImage = UIImage()
    let newImage = UIImage()
    cell.configure(first)
    requestCover(cell: cell, id: first.id, source: source)
    cell.prepareForReuse()
    cell.configure(second)
    requestCover(cell: cell, id: second.id, source: source)
    source.finish(id: second.id, image: newImage)
    source.finish(id: first.id, image: oldImage)
    assert(cell.imageView?.image === newImage)
}

